			if result.Age < 0 {
				return result, &validation.GTEError{Pos: s.Offset(), Path: []string{"age"}, Limit: 0, Value: result.Age}
			}
			if result.Age > 150 {
				return result, &validation.LTEError{Pos: s.Offset(), Path: []string{"age"}, Limit: 150, Value: result.Age}
			}
